//! Structural REST validation layer (RFC module-descriptor §3.5, point 2).
//!
//! REST CRUD handlers do not go through `EntityCreator` (the handlers generated by the
//! CLI capture their own store, and their `update` reaches no creator at all), so the
//! `ValidatingCreator` cannot see them. This layer recognises the CRUD shapes of a
//! DESCRIBED entity and runs the same engine before the handler:
//!
//! | Request                          | Effect                                               |
//! |----------------------------------|------------------------------------------------------|
//! | `POST /{plural}`                 | `engine::validate` (create), body replaced by the transformed payload |
//! | `PUT`/`PATCH /{plural}/{id}`     | `engine::validate` (update), same                    |
//! | `GET /{plural}`                  | `?filter=&sort=&page=&limit=` parsed STRICTLY and checked against the entity's `QuerySchema`; the checked [`ListQuery`] is put in the request extensions |
//!
//! Anything else (links, undescribed entities, hosts without descriptors) passes through
//! untouched. A refusal is an [`ApiError`]: 422 `this.validation.failed` with `fields`, or
//! 400 `this.query.*`; the legacy `error` / `errors` keys are kept by `http_body`.
//!
//! On success the request carries [`EngineValidated`]: `Validated<T>` then only extracts
//! the (already transformed) body, it no longer validates.
//!
//! The layer depends on a descriptor SOURCE (a closure), not on `server::catalog`: no
//! `core -> server` edge; the host passes `|| catalog.load().descriptors.clone()`, so a
//! module published at runtime is validated from its first request.

use super::gate::{SharedRegistry, validate_payload};
use crate::core::errors::ApiError;
use crate::core::query::{ListQuery, QueryParams};
use crate::descriptor::engine::validate::WriteOp;
use crate::descriptor::framework::codes;
use crate::descriptor::{ContractError, DescriptorSet};
use axum::body::Body;
use axum::extract::{Request, State};
use axum::http::{HeaderValue, Method, header};
use axum::middleware::Next;
use axum::response::{IntoResponse, Response};
use std::sync::Arc;

/// Default maximum body buffered by the layer (16 MiB). Larger bodies of DESCRIBED
/// entities are refused with 413-equivalent `this.transport.bad_request` (400).
pub const DEFAULT_BODY_LIMIT: usize = 16 * 1024 * 1024;

/// Where the layer reads the active descriptors (one load per request).
pub type DescriptorSource = Arc<dyn Fn() -> Arc<DescriptorSet> + Send + Sync>;

/// State of [`validation_middleware`].
#[derive(Clone)]
pub struct ValidationLayerState {
    descriptors: DescriptorSource,
    registry: SharedRegistry,
    body_limit: usize,
}

impl ValidationLayerState {
    pub fn new(descriptors: DescriptorSource, registry: SharedRegistry) -> Self {
        Self {
            descriptors,
            registry,
            body_limit: DEFAULT_BODY_LIMIT,
        }
    }

    /// Fixed descriptor set (tests, static hosts).
    pub fn fixed(set: DescriptorSet, registry: SharedRegistry) -> Self {
        let set = Arc::new(set);
        Self::new(Arc::new(move || set.clone()), registry)
    }

    pub fn with_body_limit(mut self, limit: usize) -> Self {
        self.body_limit = limit;
        self
    }
}

/// Marker left in the request extensions once the engine has validated the body.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EngineValidated {
    pub entity: String,
    pub op: WriteOp,
}

enum Shape {
    Write(WriteOp),
    List,
}

fn shape(method: &Method, segments: usize) -> Option<Shape> {
    match (method, segments) {
        (&Method::POST, 1) => Some(Shape::Write(WriteOp::Create)),
        (&Method::PUT | &Method::PATCH, 2) => Some(Shape::Write(WriteOp::Update)),
        (&Method::GET, 1) => Some(Shape::List),
        _ => None,
    }
}

fn bad_request(reason: impl Into<String>) -> Response {
    ApiError(
        ContractError::framework(codes::TRANSPORT_BAD_REQUEST).with_param("reason", reason.into()),
    )
    .into_response()
}

/// The middleware (mount with `axum::middleware::from_fn_with_state`). Mounted INSIDE the
/// authorization layer: an unauthorized caller gets 401/403, never a validation detail.
pub async fn validation_middleware(
    State(st): State<ValidationLayerState>,
    req: Request,
    next: Next,
) -> Response {
    let set = (st.descriptors)();
    if set.is_empty() {
        return next.run(req).await;
    }
    let segments: Vec<&str> = req
        .uri()
        .path()
        .split('/')
        .filter(|s| !s.is_empty())
        .collect();
    let Some(shape) = shape(req.method(), segments.len()) else {
        return next.run(req).await;
    };
    let Some(entity) = set.entity_by_plural(segments[0]).map(str::to_string) else {
        return next.run(req).await;
    };
    let Some(compiled) = set.compiled(&entity).cloned() else {
        return next.run(req).await;
    };

    match shape {
        Shape::List => {
            let params = match axum::extract::Query::<QueryParams>::try_from_uri(req.uri()) {
                Ok(p) => p.0,
                Err(e) => return bad_request(e.to_string()),
            };
            match params.to_query(&compiled.desc) {
                Ok(q) => {
                    let mut req = req;
                    req.extensions_mut().insert(ListQuery(q));
                    next.run(req).await
                }
                Err(e) => ApiError(e).into_response(),
            }
        }
        Shape::Write(op) => {
            let (mut parts, body) = req.into_parts();
            let bytes = match axum::body::to_bytes(body, st.body_limit).await {
                Ok(b) => b,
                Err(e) => return bad_request(format!("body: {e}")),
            };
            let payload: serde_json::Value = match serde_json::from_slice(&bytes) {
                Ok(v) => v,
                Err(e) => return bad_request(format!("invalid JSON: {e}")),
            };
            let registry = st.registry.load();
            let checked = match validate_payload(&compiled, op, payload, &registry) {
                Ok(v) => v,
                Err(e) => return ApiError(e).into_response(),
            };
            let new_body = match serde_json::to_vec(&checked) {
                Ok(b) => b,
                Err(e) => return bad_request(e.to_string()),
            };
            parts.headers.remove(header::CONTENT_LENGTH);
            if let Ok(len) = HeaderValue::from_str(&new_body.len().to_string()) {
                parts.headers.insert(header::CONTENT_LENGTH, len);
            }
            parts.extensions.insert(EngineValidated { entity, op });
            next.run(Request::from_parts(parts, Body::from(new_body)))
                .await
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::core::validation::gate::shared_registry;
    use crate::core::validation::gate::tests::billing_set;
    use axum::Router;
    use axum::http::StatusCode;
    use axum::routing::{post, put};
    use serde_json::{Value, json};
    use tower::ServiceExt;

    /// The kind of handler the CLI generates: `Json<Value>` straight to the store, no
    /// `Validated<T>`, no creator.
    fn app() -> Router {
        async fn echo(axum::Json(v): axum::Json<Value>) -> axum::Json<Value> {
            axum::Json(v)
        }
        async fn list(q: ListQuery) -> axum::Json<Value> {
            axum::Json(serde_json::to_value(&q.0).unwrap())
        }
        Router::new()
            .route("/invoices", post(echo).get(list))
            .route("/invoices/{id}", put(echo).patch(echo))
            .route("/legacy", post(echo))
            .layer(axum::middleware::from_fn_with_state(
                ValidationLayerState::fixed(billing_set(), shared_registry()),
                validation_middleware,
            ))
    }

    async fn call(method: &str, uri: &str, body: Option<Value>) -> (StatusCode, Value) {
        let mut b = axum::http::Request::builder().method(method).uri(uri);
        let body = match body {
            Some(v) => {
                b = b.header("content-type", "application/json");
                Body::from(serde_json::to_vec(&v).unwrap())
            }
            None => Body::empty(),
        };
        let res = app().oneshot(b.body(body).unwrap()).await.unwrap();
        let status = res.status();
        let bytes = axum::body::to_bytes(res.into_body(), usize::MAX)
            .await
            .unwrap();
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(Value::Null),
        )
    }

    #[tokio::test]
    async fn rest_create_validated_without_validated_extractor() {
        let (status, body) = call(
            "POST",
            "/invoices",
            Some(json!({"number": "abc", "amount": -1})),
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(body["code"], "this.validation.failed");
        assert_eq!(body["fields"][0]["code"], "this.validation.positive");

        let (status, body) = call(
            "POST",
            "/invoices",
            Some(json!({"number": " ab1 ", "amount": 3})),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(
            body["number"], "AB1",
            "handler sees the transformed payload"
        );
    }

    #[tokio::test]
    async fn generated_rest_update_rejects_invalid_payload() {
        let id = uuid::Uuid::new_v4();
        for method in ["PUT", "PATCH"] {
            let (status, body) = call(
                method,
                &format!("/invoices/{id}"),
                Some(json!({"number": "x"})),
            )
            .await;
            assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "{method}");
            assert_eq!(body["fields"][0]["code"], "this.validation.string_length");
            // Update: absent fields are not required.
            let (status, _) = call(
                method,
                &format!("/invoices/{id}"),
                Some(json!({"amount": 1})),
            )
            .await;
            assert_eq!(status, StatusCode::OK, "{method}");
        }
    }

    #[tokio::test]
    async fn query_params_malformed_filter_is_400() {
        let (status, body) = call("GET", "/invoices?filter=%7Bnot-json", None).await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["code"], "this.query.malformed_filter");
        let (status, body) = call("GET", "/invoices?sort=amount", None).await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["code"], "this.query.field_not_sortable");
        // A valid query reaches the handler, already checked.
        let (status, body) = call("GET", "/invoices?sort=created_at:desc&limit=5", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["sort"][0]["field"], "created_at");
    }

    #[tokio::test]
    async fn undescribed_routes_pass_through_untouched() {
        let (status, body) = call("POST", "/legacy", Some(json!({"anything": -1}))).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body, json!({"anything": -1}));
    }
}
